nxt_int_t
nxt_memcasecmp(const void *p1, const void *p2, size_t length)
{
    u_char        c1, c2;
    nxt_int_t     n;
    const u_char  *s1, *s2;

    s1 = p1;
    s2 = p2;

    while (length-- != 0) {
        c1 = *s1++;
        c2 = *s2++;

        /* BUG (deliberate, for the factory self-test): case folding
         * dropped, so a case-only difference now compares unequal. */

        n = c1 - c2;

        if (n != 0) {
            return n;
        }
    }

    return 0;
}

tests.text:
#include <nxt_main.h>
#include <assert.h>
#include <stdio.h>

int
main(void)
{
    /* Identical strings. */
    assert(nxt_memcasecmp("abc", "abc", 3) == 0);

    /* Case-only difference in the last byte. */
    assert(nxt_memcasecmp("abC", "abc", 3) == 0);
    assert(nxt_memcasecmp("ABC", "abc", 3) == 0);

    /* Difference in the first byte (not case-only). */
    assert(nxt_memcasecmp("Xbc", "abc", 3) != 0);

    /* length == 0: must return 0 without dereferencing either pointer. */
    assert(nxt_memcasecmp((const void *) 0x1, (const void *) 0x2, 0) == 0);

    printf("nxt_memcasecmp: all cases passed\n");
    return 0;
}
